import pandas as pd

def find_managers(employee: pd.DataFrame) -> pd.DataFrame:
    if employee.empty:
        return pd.DataFrame(columns=['name'])
    emp = employee.dropna(subset=['managerId']).copy()
    if emp.empty:
        return pd.DataFrame(columns=['name'])
    emp['managerId'] = emp['managerId'].astype(employee['id'].dtype)
    counts = emp.groupby('managerId').size().reset_index(name='report_count')
    eligible = counts[counts['report_count'] >= 5]
    res = eligible.merge(employee, left_on='managerId', right_on='id')
    return res[['name']]
